<script>
(function(){
    // 获取当前脚本所在的界面容器
    var root = document.currentScript ? document.currentScript.closest('.wbot') || document.querySelector('.wbot:last-of-type') : document.querySelector('.wbot:last-of-type');
    if (!root) return;

    // 解析"emoji昵称"→ 分离头像emoji和纯昵称
    function parseNameField(raw) {
        if (!raw) return { emoji: '👤', name: '' };
        raw = raw.trim();
        // 尝试匹配开头的emoji（包括组合emoji）
        var m = raw.match(/^([\u{1F000}-\u{1FFFF}]|[\u{2600}-\u{27BF}]|[\u{FE00}-\u{FEFF}]|[\u{1F900}-\u{1F9FF}]|[\u{200D}\u{20E3}\u{FE0F}]|[⭐🌙🔭🎮🖤💀👻🐾🌸✨🎪🎭🎨🦊🐱🐰🎀💫🌟☀️🌈🍓🍰🎵🎶💜💙💚💛🧡❤️🤍🖤🩷🩵🩶])+/u);
        if (m) {
            return { emoji: m[0], name: raw.slice(m[0].length).trim() };
        }
        return { emoji: '👤', name: raw };
    }

    // 解析"时间 · 互动数据"→ 分离时间和互动
    function parseMeta(raw) {
        if (!raw) return { time: '', stats: '' };
        raw = raw.trim();
        var idx = raw.indexOf('·');
        if (idx === -1) idx = raw.indexOf('·');
        if (idx !== -1) {
            return { time: raw.substring(0, idx).trim(), stats: raw.substring(idx + 1).trim() };
        }
        // 如果没有分隔符，尝试用🔁分割
        var ri = raw.indexOf('🔁');
        if (ri > 0) {
            return { time: raw.substring(0, ri).trim(), stats: raw.substring(ri).trim() };
        }
        return { time: raw, stats: '' };
    }

    // 解析"粉丝数关注关注数" → 两个数字
    function parseData(raw) {
        if (!raw) return { fans: '0', follow: '0' };
        raw = raw.trim();
        var m = raw.match(/(\d+)\s*关注\s*(\d+)/);
        if (m) return { fans: m[1], follow: m[2] };
        // 尝试反向
        m = raw.match(/(\d+).*?(\d+)/);
        if (m) return { fans: m[1], follow: m[2] };
        return { fans: '0', follow: '0' };
    }

    // 处理带有data-name属性的头像和昵称元素
    root.querySelectorAll('[data-name]').forEach(function(el) {
        var parsed = parseNameField(el.getAttribute('data-name'));
        if (el.classList.contains('wav') || el.classList.contains('wstk-av')) {
            el.textContent = parsed.emoji;
        } else if (el.classList.contains('wnick') || el.classList.contains('wstk-nm')) {
            // 保留已有的子元素（如小号标签）
            var existingChildren = [];
            el.childNodes.forEach(function(c) {
                if (c.nodeType === 1) existingChildren.push(c);
            });
            el.textContent = parsed.name;
            // 如果是VT面板的昵称，添加认证标记
            if (el.closest('.wcard-vt')) {
                // 检查名字里是否包含认证信息
                var badgeText = '';
                var nameClean = parsed.name;
                var certIdx = parsed.name.indexOf('🔷');
                if (certIdx !== -1) {
                    nameClean = parsed.name.substring(0, certIdx).trim();
                    badgeText = parsed.name.substring(certIdx).trim();
                }
                el.textContent = nameClean;
                if (badgeText) {
                    var badge = document.createElement('span');
                    badge.className = 'wvt-badge';
                    badge.textContent = badgeText;
                    el.appendChild(badge);
                }
            }
            // 恢复子元素
            existingChildren.forEach(function(c) { el.appendChild(c); });
        }
    });

    // 处理带有data-meta属性的时间和互动元素
    root.querySelectorAll('[data-meta]').forEach(function(el) {
        var parsed = parseMeta(el.getAttribute('data-meta'));
        if (el.classList.contains('wtm')) {
            el.textContent = parsed.time;
        } else if (el.classList.contains('wact')) {
            el.textContent = parsed.stats;
        }
    });

    // 处理stalked的粉丝关注数据
    var statsEl = root.querySelector('.wstk-stats[data-raw]');
    if (statsEl) {
        var d = parseData(statsEl.getAttribute('data-raw'));
        statsEl.innerHTML = '<span><span class="wstk-sn">' + d.fans + '</span>粉丝</span><span><span class="wstk-sn">' + d.follow + '</span>关注</span>';
    }
})();

// 标签切换
function wbotTab(tabEl, panelId) {
    var c = tabEl.closest('.wbot');
    if (!c) return;
    c.querySelectorAll('.wbot-tb').forEach(function(t) { t.classList.remove('wtb-on'); });
    tabEl.classList.add('wtb-on');
    c.querySelectorAll('.wbot-pn').forEach(function(p) { p.classList.remove('wpn-on'); });
    var t = c.querySelector('#' + panelId);
    if (t) t.classList.add('wpn-on');
}
</script>

